// Bloque 2.2 — normalización de la entrada.
//
// Todo lo que sabe el resto del workflow sobre el mensaje sale de aquí. Es el
// único nodo que conoce la forma del canal: el día que además de la web entre
// WhatsApp, se toca ESTE nodo y nada más.
//
// También es el primer guardarraíl (9.6): el texto del cliente se limpia antes
// de acercarse al modelo. Los caracteres de control y los saltos de línea son
// el envoltorio habitual de una inyección de prompt, y en un chat no hacen
// ninguna falta.

const cuerpo = $input.first().json.body ?? {};

function limpiar(valor, maximo) {
  if (typeof valor !== 'string') return '';
  return valor
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, maximo);
}

const usuario = cuerpo.usuario ?? {};

// La ficha del cliente llega de la app, que la sacó de la sesión, y no se
// consulta desde aquí (bloques 3.2 y 3.7). Dos motivos: la app ya la tiene
// autenticada, y así n8n nunca necesita permiso de lectura sobre la tabla de
// clientes. Lo que no puede leer, no puede filtrar.
return [{
  json: {
    sessionId:   limpiar(cuerpo.sessionId, 100),
    mensajeId:   limpiar(cuerpo.mensajeId, 100),
    texto:       limpiar(cuerpo.texto, 1000),
    canal:       'web',
    autenticado: Boolean(usuario.id),
    usuario: {
      id:       limpiar(usuario.id, 60) || null,
      nombre:   limpiar(usuario.nombre, 80),
      telefono: limpiar(usuario.telefono, 30),
      email:    limpiar(usuario.email, 120),
    },
    recibidoEn: new Date().toISOString(),
  },
}];

// Bloque 9 — guardarraíl de salida, y de paso la materia prima del log.
//
// Lo que sale del agente no va al cliente sin pasar por aquí. Cuatro cosas:
// que no vaya vacío, que no se haya llevado el prompt por delante, que no
// enseñe las tripas de la base de datos, y que quepa en una burbuja de chat.

const CANARIO = 'ROSSO-4417';

// Segunda comprobación del prompt, por si el canario se pierde en una
// paráfrasis o en una traducción: la primera línea del system prompt no tiene
// por qué aparecer nunca en una respuesta de chat.
const FRAGMENTO_PROMPT = 'ERES NINA, LA ANFITRIONA';

// Fuga de esquema. Las tools van con onError=continueRegularOutput, así que un
// fallo de Postgres ya no tumba el turno: entra en el contexto del modelo como
// resultado de la herramienta. Y lo que entra en el contexto, el modelo lo
// puede repetir en la burbuja. El nombre de una constraint, de una tabla o de
// un schema no es asunto de quien pregunta por una pizza.
const RASTROS_TECNICOS = [
  'AGENTE.',
  'PUBLIC.',
  'VIOLATES',
  'CONSTRAINT',
  'SQLSTATE',
  'ERROR:',
  'DUPLICATE KEY',
];

const MAXIMO = 1200;
const CORTESIA =
  'Perdona, se me ha cruzado un cable. ¿Me lo repites? Si es urgente, llámanos.';

const salida = $input.first().json;
const entrada = $('Normalizar entrada').first().json;

let texto = typeof salida.output === 'string' ? salida.output.trim() : '';
let incidencia = null;

// Todo se compara en mayúsculas: 'rosso-4417' es exactamente la misma fuga que
// 'ROSSO-4417', y al modelo nadie le ha prometido respetar la caja.
const enMayusculas = texto.toUpperCase();
const rastro = RASTROS_TECNICOS.find((r) => enMayusculas.includes(r));

if (!texto) {
  // Un agente que devuelve vacío deja al usuario mirando una burbuja en blanco,
  // que es peor que un error: no sabe si escribir otra vez o esperar (2.10).
  incidencia = 'el agente devolvió una respuesta vacía';
  texto = CORTESIA;
} else if (enMayusculas.includes(CANARIO)) {
  // El canario vive en el system prompt con la orden de no escribirlo nunca. Si
  // aparece aquí, el prompt se ha filtrado: no se le enseña al cliente y queda
  // registrado para poder mirarlo.
  incidencia = 'posible fuga del system prompt (canario en la salida)';
  texto = CORTESIA;
} else if (enMayusculas.includes(FRAGMENTO_PROMPT)) {
  incidencia = 'posible fuga del system prompt (fragmento literal en la salida)';
  texto = CORTESIA;
} else if (rastro) {
  incidencia = 'posible fuga de esquema en la salida (rastro «' + rastro + '»)';
  texto = CORTESIA;
} else if (texto.length > MAXIMO) {
  texto = texto.slice(0, MAXIMO).replace(/\s\S*$/, '') + '…';
}

// Qué modelo contestó. El nodo Agent NO lo dice: su salida es
// { output, intermediateSteps } y no publica qué modelo la produjo. Aquí eso da
// igual porque `needsFallback` está desactivado y solo hay UN modelo colgado del
// agente, así que este literal no es una aproximación: es el dato exacto.
//
// Importa que coincida con el id del nodo de modelo. `agente.consumo_hoy()`
// cruza este texto con `agente.precios` para calcular el gasto del día, y una
// discrepancia no falla ni avisa: solo mueve el presupuesto. Reportar
// 'claude-opus-5' mientras contesta gpt-4.1-mini multiplica el gasto por doce
// (5/25 $ el millón contra 0,40/1,60) y el tope de 5 $ salta con 40 céntimos
// gastados; al revés, el tope no salta nunca.
//
// Si algún día vuelve a haber respaldo, esto deja de ser exacto y hay que
// escoger: reportar el CARO —sesga hacia cortar antes, que es el lado seguro— o
// partir el fallback en dos ramas explícitas, cada una reportando su id, que es
// la salida limpia que propone el informe de la revisión.
const MODELO_REPORTADO = 'gpt-4.1-mini';


// Qué herramientas usó, para poder contestar a «¿por qué dijo eso?» (11.1).
const pasos = Array.isArray(salida.intermediateSteps) ? salida.intermediateSteps : [];
const herramientas = [...new Set(
  pasos.map((p) => p?.action?.tool).filter(Boolean),
)].join(',');

return [{
  json: {
    respuesta: texto,
    modelo: MODELO_REPORTADO,
    incidencia,
    herramientas,
    latenciaMs: Date.now() - new Date(entrada.recibidoEn).getTime(),
    tokensEntrada: salida.tokenUsage?.promptTokens ?? null,
    tokensSalida: salida.tokenUsage?.completionTokens ?? null,
  },
}];

// Adaptador del Chat Trigger a la forma que espera el Webhook.
//
// Existe para poder probar el agente entero —cuota, guardarraíl, turnos, tools,
// blindaje— desde el panel de chat de n8n, sin pasar por la app. El resto
// del workflow no se entera de por dónde entró el mensaje: este nodo es el único
// que conoce las dos formas, igual que "Normalizar entrada" es el único que
// conoce la del canal.
//
// El sessionId lleva prefijo `chat:` a propósito: las conversaciones de prueba
// quedan separadas de las reales en agente.turnos y en la memoria del agente,
// así que se pueden borrar con un `delete ... where session_id like 'chat:%'`.
//
// El mensajeId tiene que ser único por mensaje o `agente.registrar_turno` lo
// tomará por un reintento y devolverá la respuesta anterior sin volver a pensar.
const e = $input.first().json;

return [{
  json: {
    body: {
      texto: e.chatInput,
      sessionId: 'chat:' + e.sessionId,
      mensajeId: e.sessionId + ':' + $execution.id,
      usuario: {},
    },
  },
}];

// Bloque 13 — el aviso operativo. El único sitio del workflow que mira cuánto se
// lleva gastado, y el único que puede decirlo en voz alta.
//
// DÓNDE VA, y por qué importa: colgado de los nodos «Responder…», no del camino
// que lleva a ellos. Cuando esto se ejecuta, el cliente ya tiene su burbuja: un
// aviso al dueño no puede añadir ni un milisegundo a lo que espera quien
// preguntó por una pizza, ni comerse el `executionTimeout` de 25 s.
//
// A DÓNDE VA: a `agente.avisos`, por `agente.registrar_aviso()`. Antes esto
// acababa en un Telegram; el dueño decidió el 2026-09-17 que no se usa. La base
// de datos es el sitio que NO necesita una credencial nueva, así que es lo que
// puede funcionar hoy. Ojo con lo que eso significa: esto REGISTRA, no empuja.
// Hay que ir a mirarlo con `select * from agente.avisos_recientes()`. El día que
// haya un canal de verdad se cuelga de este mismo nodo.
//
// EL ANTISPAM YA NO ESTÁ AQUÍ. Vivía en `$getWorkflowStaticData('global')` y
// tenía dos modos de fallo escritos en el propio comentario: si el estado no
// llegaba a persistir el aviso se repetía, y si dos mensajes entraban a la vez
// los dos podían avisar. Ahora es un índice único en (nivel, día local, huella),
// o sea que lo garantiza Postgres. `registrar_aviso()` devuelve false cuando el
// pestillo lo traga.

// `.first()` a secas devuelve undefined aquí: `Comprobar cuota` tiene DOS salidas
// por su `onError: continueErrorOutput`, y la resolución por defecto no acierta la
// rama (medido: .all() -> [], .first() -> undefined, .first(0,0) -> la fila). Hay
// que nombrar la rama y la ejecución. El `?? {}` no es adorno: si cuota se fue por
// la salida de error, la 0 está vacía, `c.permitido` no es booleano y el aviso sale
// como 'fallo' — que es justo lo que pide el bloque de abajo.
const c = $('Comprobar cuota').first(0, 0)?.json ?? {};

// `agente.cuota` devuelve SIEMPRE una fila y `permitido` siempre es booleano.
// Si aquí no hay booleano no contestó la función: contestó la rama de error del
// nodo. Ese caso también corta el chat (falla cerrado) y también hay que
// contarlo — con `onError: continueErrorOutput` el errorWorkflow no se dispara
// para ese nodo, así que si no avisa esto no avisa nadie.
const falloDeNodo = typeof c.permitido !== 'boolean';

let nivel = null;
if (falloDeNodo) {
  nivel = 'fallo';
} else if (!c.permitido) {
  nivel = 'corte';
} else if (c.aviso) {
  nivel = 'aviso';
}

if (!nivel) return [];

// `numeric` de Postgres llega como cadena, no como número: node-postgres no lo
// convierte para no perder precisión. Y llega null en los cortes que no llegaron
// a medir (el interruptor de pánico, el fallo interno de la función). Un null
// pintado como «0.00 $» sería mentir justo en el aviso que hay que creerse.
const usd = (v) =>
  v === null || v === undefined ? '(desconocido)' : `${Number(v).toFixed(2)} $`;

const titulo = {
  fallo: 'No se puede comprobar el presupuesto',
  corte: 'El chat se ha cortado solo',
  aviso: 'El presupuesto del día va justo',
}[nivel];

const lineas = [];

if (falloDeNodo) {
  lineas.push(
    'La consulta a agente.cuota() no ha contestado, así que el chat está',
    'rechazando mensajes por precaución. Falla cerrado a propósito.',
    `Detalle: ${String(c.error?.message ?? c.error ?? 'sin detalle').slice(0, 300)}`,
  );
} else {
  lineas.push(
    `Gastado hoy: ${usd(c.gastado_usd)} de ${usd(c.tope_usd)}`,
    `Motivo: ${c.motivo}`,
  );
  if (nivel === 'corte') {
    lineas.push(
      '',
      'El chat ya no atiende. Para reabrirlo hoy, desde el SQL Editor:',
      'update agente.limites set gasto_diario_max_usd = <nuevo>;',
    );
  }
}

lineas.push(
  '',
  'No hay tope de gasto en la consola del proveedor. Esto es lo único que hay.',
);

// Sin datos del cliente en el aviso: ni el texto del mensaje, ni el teléfono, ni
// el sessionId (bloque 10). Esto lo va a leer una persona para decidir si sube el
// presupuesto, no para saber quién escribió. Las cifras SÍ salen, y solo aquí:
// ningún nodo «Responder…» las toca, que es la regla 4 del limitador.
return [{
  json: {
    nivel,
    titulo,
    detalle: lineas.join('\n'),
    contexto: {
      gastado_usd: c.gastado_usd ?? null,
      tope_usd: c.tope_usd ?? null,
      motivo: c.motivo ?? null,
      execution_id: $execution.id,
    },
    // Vacía a propósito: para los avisos de presupuesto el pestillo tiene que
    // dar UNO por nivel y por día. La huella solo la llenan las ejecuciones
    // caídas, que necesitan distinguir un fallo de otro.
    huella: '',
  },
}];
